using System;using System.IO;using System.Linq;using SargasPC;
class ReliabilityTests {
 static int n;static void Check(bool b){if(!b)throw new Exception("reliability "+n);n++;}static void Reject(Action action){bool hit=false;try{action();}catch(Exception e) when(e is IOException||e is ArgumentException||e is InvalidOperationException){hit=true;}Check(hit);}
 static void Main(){string root=Path.Combine(Path.GetTempPath(),"sargon-stability-"+Guid.NewGuid());Directory.CreateDirectory(root);try{
 var store=new AlertStore(root);Check(!store.HasPending());store.Append("engine finding");Check(store.HasPending());var first=store.Read();Check(first.Length==1&&first[0].Report=="engine finding");Check(first[0].At>0&&first[0].Id.Length==32);Check(new AlertStore(root).HasPending());store.Append("second finding");store.Acknowledge(new[]{first[0].Id});Check(store.Read().Length==1&&store.Read()[0].Report=="second finding");string before=File.ReadAllText(store.PathName);store.Acknowledge(new[]{"not-an-existing-id"});Check(store.Read().Length==1);store.Acknowledge(store.Read().Select(x=>x.Id).ToArray());Check(!store.HasPending());
 store.Append(new string('ė',10000));Check(store.Read()[0].Report.Length<=4000&&store.Read()[0].Report.Contains("sutrumpinta"));store.Acknowledge(store.Read().Select(x=>x.Id).ToArray());for(int i=0;i<20;i++)store.Append("finding "+i);Check(store.Read().Length==20);before=File.ReadAllText(store.PathName);Reject(()=>store.Append("overflow"));Check(File.ReadAllText(store.PathName)==before);
 File.WriteAllText(store.PathName,"null");Reject(()=>store.Read());File.WriteAllText(store.PathName,"{}");Reject(()=>store.Read());File.WriteAllText(store.PathName,"bad-json");Reject(()=>store.Append("must not overwrite"));Check(File.ReadAllText(store.PathName)=="bad-json");
 File.WriteAllText(store.PathName,Data.Json().Serialize(new[]{new AlertEvidence{Id="x",At=long.MaxValue,Report="bad-date"}}));Reject(()=>store.Read());File.WriteAllText(store.PathName,new string('x',400001));Reject(()=>store.Read());
 var retry=new MonitorRecovery();long now=DateTime.UtcNow.Ticks;Check(retry.Due(now)&&!retry.Due(0));retry.Failed(now);Check(retry.Failures==1&&!retry.Due(now));Check(retry.RetryAt==now+TimeSpan.FromMinutes(1).Ticks);Check(retry.Due(retry.RetryAt));retry.Failed(now);Check(retry.RetryAt==now+TimeSpan.FromMinutes(2).Ticks);for(int i=0;i<20;i++)retry.Failed(now);Check(retry.Failures==5&&retry.RetryAt==now+TimeSpan.FromMinutes(16).Ticks);retry.Succeeded();Check(retry.Failures==0&&retry.Due(now));Console.WriteLine("PASS: "+n+" reliability checks (persistent evidence, selective acknowledgement, bounded/corrupt journal, restore backoff; no real malware or Windows service test).");
 }finally{Directory.Delete(root,true);}}
}
